{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPp9ODTkFtoC1QmNrWl+HAI"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","source":["!pip install -q gradio"],"metadata":{"id":"OFu_TEMUuWNM","executionInfo":{"status":"ok","timestamp":1790443102074,"user_tz":-345,"elapsed":11358,"user":{"displayName":"saniya poudel","userId":"18331242018186364025"}}},"execution_count":9,"outputs":[]},{"cell_type":"code","source":["import gradio as gr\n","import pandas as pd\n","import joblib\n","model = joblib.load(\"adult_income_classifier.pkl\")\n","print(\"Model loaded successfully!\")"],"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"1a-tie16tCta","executionInfo":{"status":"ok","timestamp":1790443177563,"user_tz":-345,"elapsed":5191,"user":{"displayName":"saniya poudel","userId":"18331242018186364025"}},"outputId":"f1d474ea-07fb-48eb-d4ff-376ff0c531e9"},"execution_count":10,"outputs":[{"output_type":"stream","name":"stdout","text":["Model loaded successfully!\n"]}]},{"cell_type":"code","source":["import gradio as gr\n","import pandas as pd\n","import joblib\n","\n","model = joblib.load(\"adult_income_classifier.pkl\")\n","\n","def predict_income(\n","    age,\n","    workclass,\n","    fnlwgt,\n","    educational_num,\n","    marital_status,\n","    occupation,\n","    relationship,\n","    race,\n","    gender,\n","    capital_gain,\n","    capital_loss,\n","    hours_per_week,\n","    native_country\n","):\n","\n","\n","    total_capital = capital_gain - capital_loss\n","\n","    if age <= 25:\n","        age_group = \"Young\"\n","    elif age <= 35:\n","        age_group = \"Early_Adult\"\n","    elif age <= 50:\n","        age_group = \"Middle_Age\"\n","    elif age <= 65:\n","        age_group = \"Senior\"\n","    else:\n","        age_group = \"Older\"\n","\n","\n","    input_data = pd.DataFrame([{\n","        \"age\": age,\n","        \"workclass\": workclass,\n","        \"fnlwgt\": fnlwgt,\n","        \"educational-num\": educational_num,\n","        \"marital-status\": marital_status,\n","        \"occupation\": occupation,\n","        \"relationship\": relationship,\n","        \"race\": race,\n","        \"gender\": gender,\n","        \"capital-gain\": capital_gain,\n","        \"capital-loss\": capital_loss,\n","        \"hours-per-week\": hours_per_week,\n","        \"native-country\": native_country,\n","        \"total-capital\": total_capital,\n","        \"age-group\": age_group\n","    }])\n","\n","\n","    prediction = model.predict(input_data)[0]\n","    probability = model.predict_proba(input_data)[0]\n","\n","    if prediction == 1:\n","        result = \">50K\"\n","    else:\n","        result = \"<=50K\"\n","\n","    return (\n","        f\"Predicted Income: {result}\",\n","        f\"Probability <=50K: {probability[0] * 100:.2f}%\",\n","        f\"Probability >50K: {probability[1] * 100:.2f}%\"\n","    )\n","\n","\n","\n","demo = gr.Interface(\n","    fn=predict_income,\n","\n","    inputs=[\n","        gr.Number(label=\"Age\", value=35),\n","        gr.Textbox(label=\"Workclass\", value=\"Private\"),\n","        gr.Number(label=\"fnlwgt\", value=200000),\n","        gr.Number(label=\"Educational Number\", value=13),\n","        gr.Textbox(label=\"Marital Status\", value=\"Married-civ-spouse\"),\n","        gr.Textbox(label=\"Occupation\", value=\"Exec-managerial\"),\n","        gr.Textbox(label=\"Relationship\", value=\"Husband\"),\n","        gr.Textbox(label=\"Race\", value=\"White\"),\n","        gr.Textbox(label=\"Gender\", value=\"Male\"),\n","        gr.Number(label=\"Capital Gain\", value=0),\n","        gr.Number(label=\"Capital Loss\", value=0),\n","        gr.Number(label=\"Hours per Week\", value=40),\n","        gr.Textbox(label=\"Native Country\", value=\"United-States\")\n","    ],\n","\n","    outputs=[\n","        gr.Textbox(label=\"Prediction\"),\n","        gr.Textbox(label=\"Probability <=50K\"),\n","        gr.Textbox(label=\"Probability >50K\")\n","    ],\n","\n","    title=\"Adult Income Classification\",\n","    description=\"Predict whether annual income is <=50K or >50K.\"\n",")\n","\n","demo.launch(share=True)"],"metadata":{"colab":{"base_uri":"https://localhost:8080/","height":611},"id":"QrPMwgRgvnTd","executionInfo":{"status":"ok","timestamp":1790443427224,"user_tz":-345,"elapsed":3908,"user":{"displayName":"saniya poudel","userId":"18331242018186364025"}},"outputId":"2313a39a-8fa2-4f9f-ed15-40d99df47a96"},"execution_count":12,"outputs":[{"output_type":"stream","name":"stdout","text":["Colab notebook detected. To show errors in colab notebook, set debug=True in launch()\n","* Running on public URL: https://32ed4aa578bd4bd238.gradio.live\n","\n","This share link is temporary and will last for up to 1 week (best effort). For free permanent hosting and GPU upgrades, run `gradio deploy` from the terminal in the working directory to deploy to Hugging Face Spaces (https://huggingface.co/spaces)\n"]},{"output_type":"display_data","data":{"text/plain":["<IPython.core.display.HTML object>"],"text/html":["<div><iframe src=\"https://32ed4aa578bd4bd238.gradio.live\" width=\"100%\" height=\"500\" allow=\"autoplay; camera; microphone; clipboard-read; clipboard-write;\" frameborder=\"0\" allowfullscreen></iframe></div>"]},"metadata":{}},{"output_type":"execute_result","data":{"text/plain":[]},"metadata":{},"execution_count":12}]},{"cell_type":"code","source":[],"metadata":{"id":"tfVhTpk0voTZ"},"execution_count":null,"outputs":[]}]}